CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "274893c2-7895-4fb2-8644-16e05d91c71c",
  "snapshot_timestamp": "2026-05-21T18:29:36Z",
  "ticket_id": "36a7-dbb5",
  "items": [
    {
      "original_text": "After the cutover commit, a downstream client running /plugin marketplace update sees their installed dso plugin re-resolved to the latest release tag (not to main HEAD).",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where the plugin marketplace resolution mechanism consistently points to release tags rather than main HEAD after the cutover"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Clients can run /plugin install dso-dev@<marketplace-name> to subscribe to per-merge updates from main. Validation signal: a /plugin marketplace update after a merge to main re-resolves dso-dev to the new commit.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability (plugin installation and auto-update mechanism) that will remain true after implementation, phrased as ongoing user-facing behavior"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "A merge to main does not change the content that dso consumers see on their next marketplace refresh \u2014 only dso-dev consumers move forward.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where production consumers are isolated from development changes until intentional promotion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "scripts/release.sh cuts a release only after confirming (a) CI is green on the commit being tagged, (b) the working tree is clean and the local branch is main up-to-date with origin/main, and (c) plugins/dso/scripts/validate.sh --ci passes; the script aborts with a clear error message naming the failed precondition otherwise.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system behavior of the release script's validation logic that persists after implementation, not a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The first stable release tag (v1.13.0, the next minor bump from the current 1.12.32) is cut from main during epic execution, and the dso entry in marketplace.json is pinned to it via git-subdir.",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a specific one-time action of cutting a release tag and pinning a submodule, not an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "INSTALL.md documents both channels (install commands for dso and dso-dev, recommendation to enable auto-update on the marketplace via the /plugin UI, and a one-line statement of the version semantics \u2014 dso advances on tagged releases, dso-dev advances on every merge to main).",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "documentation of installation channels and versioning semantics is a durable property of the system that persists after this work is complete"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
